WITH recent_employees AS (SELECT * FROM employees WHERE email IS NULL), EmployeesStats AS (SELECT MONTH(hire_date) AS hire_month, MIN(hire_date) AS min_hire_date, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(level))) AS level_values FROM recent_employees GROUP BY MONTH(hire_date)) SELECT hire_month, min_hire_date, level_values FROM EmployeesStats ORDER BY min_hire_date DESC, level_values;
